fn fqdigbooks(nodes, depth) {
 if (nodes == null || depth > 4) {
 return []
 }
 let out = []
 let i = 0
 while (i < len(nodes)) {
 let one = nodes[i]
 let bd = one.book_data
 if (bd != null) {
 let j = 0
 while (j < len(bd)) {
 out = push(out, bd[j])
 j = j + 1
 }
 }
 let inner = one.cell_data
 if (inner != null) {
 let deep = fqdigbooks(inner, depth + 1)
 let k = 0
 while (k < len(deep)) {
 out = push(out, deep[k])
 k = k + 1
 }
 }
 i = i + 1
 }
 return out
}
